"""Machine Learning track content for the Holiday Data and AI Camp (revision 2, 31 Oct 2026).

Exports: ML (24 lessons), LABS (4 labs, F01 to F04), EXTENSION (optional neural-network notebook).
Schema: see ../common.py. Numbers in `check` expressions were derived a second way with
NumPy (np.linalg.lstsq for linear fits, RandomState(r).permutation for train_test_split without
stratify) because scikit-learn could not be installed where this file was written. Any lesson whose
code or checks touch scikit-learn carries needs_sklearn=True so the verifier can skip it on a machine
without scikit-learn and run it on the camp laptop.
"""


def _sk(*texts):
    return any(t and "sklearn" in t for t in texts)


def B(idea, intro, predict, code, shows, investigate, modify, check=None, nocheck=False):
    d = dict(idea=idea, intro=intro, predict=predict, code=code, shows=shows,
             investigate=investigate, modify=modify)
    if check is not None:
        d["check"] = check
    if nocheck:
        d["nocheck"] = True
    if _sk(code, check, modify.get("code"), modify.get("check")):
        d["needs_sklearn"] = True
    return d


def M(task, reference, check=None, is_code=True, evidence=""):
    d = dict(task=task, reference=reference, reference_is_code=is_code, evidence=evidence)
    if check is not None:
        d["check"] = check
    return d


def L(title, objective, question, words, blocks, make, errors, exit_ticket, mode, libs, data,
      misconceptions, questions, pacing=None, time_note=None):
    assert len(words) <= 6 and len(errors) == 2, title
    needs = any(b.get("needs_sklearn") for b in blocks) or (
        make.get("reference_is_code") and _sk(make.get("reference"), make.get("check")))
    d = dict(title=title, objective=objective, question=question, words=words, blocks=blocks,
             make=make, errors=errors, exit_ticket=exit_ticket, mode=mode, libs=libs, data=data,
             misconceptions=misconceptions, questions=questions, pacing=pacing, time_note=time_note)
    if needs:
        d["needs_sklearn"] = True
    return d


