# A word is defined once per track. Where a later session repeats a word that an earlier
# session already defined, the earlier definition stands and the later card drops it.
_seen_words = set()
for _lesson in ML:
    _keep = []
    for _w in _lesson['words']:
        _k = _w[0].strip().lower()
        if _k not in _seen_words:
            _seen_words.add(_k)
            _keep.append(_w)
    _lesson['words'] = _keep
